// apb_gpio: APB4 GPIO peripheral with edge and level interrupts.
// Implements microarchitecture.md for interface_spec.md (both approved).
`default_nettype none

module apb_gpio #(
  parameter integer ADDR_WIDTH = 8,
  parameter integer N          = 8
) (
  input  wire                  pclk,
  input  wire                  presetn,
  input  wire [ADDR_WIDTH-1:0] paddr,
  input  wire                  psel,
  input  wire                  penable,
  input  wire                  pwrite,
  input  wire [31:0]           pwdata,
  input  wire [3:0]            pstrb,
  output wire [31:0]           prdata,
  output wire                  pready,
  output wire                  pslverr,
  input  wire [N-1:0]          gpio_in,
  output wire [N-1:0]          gpio_out,
  output wire [N-1:0]          gpio_oe,
  output wire                  irq
);

  // Register indices (paddr[5:2])
  localparam [3:0] IDX_DATA_OUT    = 4'd0;
  localparam [3:0] IDX_DIR         = 4'd1;
  localparam [3:0] IDX_DATA_IN     = 4'd2;
  localparam [3:0] IDX_INTR_RISE   = 4'd3;
  localparam [3:0] IDX_INTR_FALL   = 4'd4;
  localparam [3:0] IDX_INTR_HIGH   = 4'd5;
  localparam [3:0] IDX_INTR_LOW    = 4'd6;
  localparam [3:0] IDX_INTR_ENABLE = 4'd7;
  localparam [3:0] IDX_INTR_STATUS = 4'd8;

  // Bits 0..N-1 set: the pins that exist.
  localparam [31:0] PINS = (N >= 32) ? 32'hFFFF_FFFF : ((32'd1 << N) - 32'd1);

  // ------------------------------------------------------------------
  // State
  // ------------------------------------------------------------------
  reg [31:0] data_out_q;
  reg [31:0] dir_q;
  reg [31:0] rise_en_q;
  reg [31:0] fall_en_q;
  reg [31:0] high_en_q;
  reg [31:0] low_en_q;
  reg [31:0] intr_en_q;
  reg [31:0] status_q;
  reg [31:0] in_q;
  reg [31:0] in_prev_q;

  // ------------------------------------------------------------------
  // Input widening: gpio_in to 32 bits, zeros above N
  // ------------------------------------------------------------------
  wire [31:0] in_w;
  genvar g;
  generate
    for (g = 0; g < 32; g = g + 1) begin : g_in
      if (g < N) begin : g_pin
        assign in_w[g] = gpio_in[g];
      end else begin : g_nopin
        assign in_w[g] = 1'b0;
      end
    end
  endgenerate

  // ------------------------------------------------------------------
  // APB decode (zero wait states)
  // ------------------------------------------------------------------
  wire       access = psel & penable;
  wire [3:0] index  = paddr[5:2];

  wire addr_hi_zero;
  generate
    if (ADDR_WIDTH > 6) begin : g_addr_hi
      assign addr_hi_zero = (paddr[ADDR_WIDTH-1:6] == {(ADDR_WIDTH-6){1'b0}});
    end else begin : g_addr_nohi
      assign addr_hi_zero = 1'b1;
    end
  endgenerate

  wire mapped = (paddr[1:0] == 2'b00) && addr_hi_zero && (index <= IDX_INTR_STATUS);
  wire wr     = access & pwrite & mapped;
  wire rd     = access & ~pwrite & mapped;

  wire [31:0] strb_mask = {{8{pstrb[3]}}, {8{pstrb[2]}}, {8{pstrb[1]}}, {8{pstrb[0]}}};
  wire [31:0] wmask     = strb_mask & PINS;

  wire wr_data_out = wr && (index == IDX_DATA_OUT);
  wire wr_dir      = wr && (index == IDX_DIR);
  wire wr_rise     = wr && (index == IDX_INTR_RISE);
  wire wr_fall     = wr && (index == IDX_INTR_FALL);
  wire wr_high     = wr && (index == IDX_INTR_HIGH);
  wire wr_low      = wr && (index == IDX_INTR_LOW);
  wire wr_en       = wr && (index == IDX_INTR_ENABLE);
  wire wr_status   = wr && (index == IDX_INTR_STATUS);

  // ------------------------------------------------------------------
  // Next state (combinational)
  // ------------------------------------------------------------------
  wire [31:0] data_out_d = wr_data_out ? ((data_out_q & ~wmask) | (pwdata & wmask)) : data_out_q;
  wire [31:0] dir_d      = wr_dir      ? ((dir_q      & ~wmask) | (pwdata & wmask)) : dir_q;
  wire [31:0] rise_en_d  = wr_rise     ? ((rise_en_q  & ~wmask) | (pwdata & wmask)) : rise_en_q;
  wire [31:0] fall_en_d  = wr_fall     ? ((fall_en_q  & ~wmask) | (pwdata & wmask)) : fall_en_q;
  wire [31:0] high_en_d  = wr_high     ? ((high_en_q  & ~wmask) | (pwdata & wmask)) : high_en_q;
  wire [31:0] low_en_d   = wr_low      ? ((low_en_q   & ~wmask) | (pwdata & wmask)) : low_en_q;
  wire [31:0] intr_en_d  = wr_en       ? ((intr_en_q  & ~wmask) | (pwdata & wmask)) : intr_en_q;

  wire [31:0] rise_det = in_q & ~in_prev_q;
  wire [31:0] fall_det = ~in_q & in_prev_q;
  wire [31:0] detected = ((rise_det & rise_en_q) | (fall_det & fall_en_q)
                         | (in_q & high_en_q) | (~in_q & low_en_q)) & PINS;
  wire [31:0] clear    = wr_status ? (pwdata & wmask) : 32'h0000_0000;
  // Detection is ORed last: a detection beats a clear on the same edge.
  wire [31:0] status_d = (status_q & ~clear) | detected;

  // ------------------------------------------------------------------
  // Registers: synchronous active-low reset, then q <= d
  // ------------------------------------------------------------------
  always @(posedge pclk) begin
    if (!presetn) begin
      data_out_q <= 32'h0000_0000;
      dir_q      <= 32'h0000_0000;
      rise_en_q  <= 32'h0000_0000;
      fall_en_q  <= 32'h0000_0000;
      high_en_q  <= 32'h0000_0000;
      low_en_q   <= 32'h0000_0000;
      intr_en_q  <= 32'h0000_0000;
      status_q   <= 32'h0000_0000;
      in_q       <= 32'h0000_0000;
      in_prev_q  <= 32'h0000_0000;
    end else begin
      data_out_q <= data_out_d;
      dir_q      <= dir_d;
      rise_en_q  <= rise_en_d;
      fall_en_q  <= fall_en_d;
      high_en_q  <= high_en_d;
      low_en_q   <= low_en_d;
      intr_en_q  <= intr_en_d;
      status_q   <= status_d;
      in_q       <= in_w;
      in_prev_q  <= in_q;
    end
  end

  // ------------------------------------------------------------------
  // Read multiplexer
  // ------------------------------------------------------------------
  reg [31:0] rdata;
  always @* begin
    rdata = 32'h0000_0000;
    case (index)
      IDX_DATA_OUT:    rdata = data_out_q;
      IDX_DIR:         rdata = dir_q;
      IDX_DATA_IN:     rdata = in_q;
      IDX_INTR_RISE:   rdata = rise_en_q;
      IDX_INTR_FALL:   rdata = fall_en_q;
      IDX_INTR_HIGH:   rdata = high_en_q;
      IDX_INTR_LOW:    rdata = low_en_q;
      IDX_INTR_ENABLE: rdata = intr_en_q;
      IDX_INTR_STATUS: rdata = status_q;
      default:         rdata = 32'h0000_0000;
    endcase
  end

  // ------------------------------------------------------------------
  // Outputs
  // ------------------------------------------------------------------
  assign prdata   = rd ? rdata : 32'h0000_0000;
  assign pready   = 1'b1;
  assign pslverr  = access & (~mapped | (pwrite & (index == IDX_DATA_IN)));
  assign gpio_out = data_out_q[N-1:0];
  assign gpio_oe  = dir_q[N-1:0];
  assign irq      = |(status_q & intr_en_q);

  // ------------------------------------------------------------------
  // Design-intent assertions (formal tools only)
  // ------------------------------------------------------------------
`ifdef FORMAL
  always @* begin
    assert (pready == 1'b1);
    assert (!pslverr || access);
    assert ((prdata == 32'h0000_0000) || rd);
    assert ((status_q & ~PINS) == 32'h0000_0000);
    assert ((data_out_q & ~PINS) == 32'h0000_0000);
    assert ((dir_q & ~PINS) == 32'h0000_0000);
    assert ((intr_en_q & ~PINS) == 32'h0000_0000);
    assert ((in_q & ~PINS) == 32'h0000_0000);
  end
`endif

endmodule

`default_nettype wire
=== END FILE ===

=== FILE: apb_gpio_tb.v ===
// Self-checking testbench for apb_gpio at N=8 and N=32.
`timescale 1ns/1ps
`default_nettype none

module apb_gpio_tb;

  localparam [7:0] A_DATA_OUT    = 8'h00;
  localparam [7:0] A_DIR         = 8'h04;
  localparam [7:0] A_DATA_IN     = 8'h08;
  localparam [7:0] A_INTR_RISE   = 8'h0C;
  localparam [7:0] A_INTR_FALL   = 8'h10;
  localparam [7:0] A_INTR_HIGH   = 8'h14;
  localparam [7:0] A_INTR_LOW    = 8'h18;
  localparam [7:0] A_INTR_ENABLE = 8'h1C;
  localparam [7:0] A_INTR_STATUS = 8'h20;

  reg pclk = 1'b0;
  always #5 pclk = ~pclk;

  reg        presetn = 1'b0;
  reg [7:0]  paddr   = 8'h00;
  reg        psel    = 1'b0;
  reg        penable = 1'b0;
  reg        pwrite  = 1'b0;
  reg [31:0] pwdata  = 32'h0000_0000;
  reg [3:0]  pstrb   = 4'h0;
  reg        sel     = 1'b0;   // 0: N=8 instance, 1: N=32 instance
  reg [31:0] pins    = 32'h0000_0000;

  wire [31:0] prdata8;
  wire [31:0] prdata32;
  wire        pready8;
  wire        pready32;
  wire        pslverr8;
  wire        pslverr32;
  wire [7:0]  gout8;
  wire [7:0]  goe8;
  wire [31:0] gout32;
  wire [31:0] goe32;
  wire        irq8;
  wire        irq32;

  wire psel8  = psel & ~sel;
  wire psel32 = psel & sel;

  apb_gpio #(.ADDR_WIDTH(8), .N(8)) dut8 (
    .pclk(pclk), .presetn(presetn), .paddr(paddr), .psel(psel8),
    .penable(penable), .pwrite(pwrite), .pwdata(pwdata), .pstrb(pstrb),
    .prdata(prdata8), .pready(pready8), .pslverr(pslverr8),
    .gpio_in(pins[7:0]), .gpio_out(gout8), .gpio_oe(goe8), .irq(irq8)
  );

  apb_gpio #(.ADDR_WIDTH(8), .N(32)) dut32 (
    .pclk(pclk), .presetn(presetn), .paddr(paddr), .psel(psel32),
    .penable(penable), .pwrite(pwrite), .pwdata(pwdata), .pstrb(pstrb),
    .prdata(prdata32), .pready(pready32), .pslverr(pslverr32),
    .gpio_in(pins), .gpio_out(gout32), .gpio_oe(goe32), .irq(irq32)
  );

  wire [31:0] cur_prdata  = sel ? prdata32  : prdata8;
  wire        cur_pready  = sel ? pready32  : pready8;
  wire        cur_pslverr = sel ? pslverr32 : pslverr8;
  wire [31:0] cur_gout    = sel ? gout32    : {24'h000000, gout8};
  wire [31:0] cur_goe     = sel ? goe32     : {24'h000000, goe8};
  wire        cur_irq     = sel ? irq32     : irq8;

  integer passed = 0;
  integer failed = 0;
  integer chk    = 0;
  integer phase  = 0;
  integer n_cur  = 8;
  integer i;
  integer j;
  reg [31:0] mask = 32'h0000_00FF;
  reg [31:0] top  = 32'h0000_0080;
  reg [31:0] exp_st;
  reg [31:0] bm;
  reg [7:0]  a8;
  reg [31:0] mdl [0:7];
  reg [8*64-1:0] nonce;

  // ------------------------------------------------------------------
  // Checks
  // ------------------------------------------------------------------
  task check32(input [31:0] got, input [31:0] want);
    begin
      chk = chk + 1;
      if (got !== want) begin
        failed = failed + 1;
        $error("N=%0d phase %0d check %0d: got %h, expected %h", n_cur, phase, chk, got, want);
      end else begin
        passed = passed + 1;
      end
    end
  endtask

  task check1(input got, input want);
    begin
      chk = chk + 1;
      if (got !== want) begin
        failed = failed + 1;
        $error("N=%0d phase %0d check %0d: got %b, expected %b", n_cur, phase, chk, got, want);
      end else begin
        passed = passed + 1;
      end
    end
  endtask

  function [31:0] strb_mask(input [3:0] s);
    begin
      strb_mask = {{8{s[3]}}, {8{s[2]}}, {8{s[1]}}, {8{s[0]}}};
    end
  endfunction

  function [7:0] bad_addr(input integer k);
    begin
      case (k)
        0:       bad_addr = 8'h01;
        1:       bad_addr = 8'h02;
        2:       bad_addr = 8'h03;
        3:       bad_addr = 8'h05;
        4:       bad_addr = 8'h06;
        5:       bad_addr = 8'h0B;
        6:       bad_addr = 8'h21;
        7:       bad_addr = 8'h22;
        8:       bad_addr = 8'h23;
        9:       bad_addr = 8'h24;
        10:      bad_addr = 8'h28;
        11:      bad_addr = 8'h2C;
        12:      bad_addr = 8'h30;
        13:      bad_addr = 8'h3C;
        14:      bad_addr = 8'h40;
        15:      bad_addr = 8'h44;
        16:      bad_addr = 8'h48;
        17:      bad_addr = 8'h5C;
        18:      bad_addr = 8'h60;
        19:      bad_addr = 8'h80;
        20:      bad_addr = 8'hA0;
        21:      bad_addr = 8'hC0;
        22:      bad_addr = 8'hE0;
        default: bad_addr = 8'hFC;
      endcase
    end
  endfunction

  // ------------------------------------------------------------------
  // Stimulus helpers (inputs change after the falling edge)
  // ------------------------------------------------------------------
  task tick(input integer k);
    begin
      repeat (k) @(posedge pclk);
      #1;
    end
  endtask

  task set_pins(input [31:0] v);
    begin
      @(negedge pclk);
      pins = v;
    end
  endtask

  task apb_write(input [7:0] addr, input [31:0] data, input [3:0] strb, input want_err);
    begin
      @(negedge pclk);
      paddr = addr; pwrite = 1'b1; pwdata = data; pstrb = strb;
      psel = 1'b1; penable = 1'b0;
      #1;
      check1(cur_pslverr, 1'b0);          // setup: no error
      check32(cur_prdata, 32'h0000_0000); // setup: prdata zero
      @(negedge pclk);
      penable = 1'b1;
      #1;
      check1(cur_pready, 1'b1);
      check1(cur_pslverr, want_err);
      check32(cur_prdata, 32'h0000_0000);
      @(posedge pclk);
      #1;
      psel = 1'b0; penable = 1'b0; pwrite = 1'b0; pstrb = 4'h0;
    end
  endtask

  task apb_read(input [7:0] addr, input [31:0] want_data, input want_err);
    begin
      @(negedge pclk);
      paddr = addr; pwrite = 1'b0; pwdata = 32'h0000_0000; pstrb = 4'h0;
      psel = 1'b1; penable = 1'b0;
      #1;
      check1(cur_pslverr, 1'b0);
      check32(cur_prdata, 32'h0000_0000);
      @(negedge pclk);
      penable = 1'b1;
      #1;
      check1(cur_pready, 1'b1);
      check1(cur_pslverr, want_err);
      check32(cur_prdata, want_data);
      @(posedge pclk);
      #1;
      psel = 1'b0; penable = 1'b0;
    end
  endtask

  // Mapped write; updates the model for read/write registers.
  task wr_reg(input [7:0] addr, input [31:0] data, input [3:0] strb);
    begin
      apb_write(addr, data, strb, 1'b0);
      if ((addr != A_INTR_STATUS) && (addr != A_DATA_IN)) begin
        bm = strb_mask(strb) & mask;
        mdl[addr[4:2]] = (mdl[addr[4:2]] & ~bm) | (data & bm);
      end
    end
  endtask

  task check_regs;
    begin
      for (j = 0; j < 8; j = j + 1) begin
        if (j != 2) apb_read({j[5:0], 2'b00}, mdl[j], 1'b0);
      end
      apb_read(A_DATA_IN, pins & mask, 1'b0);
      check32(cur_gout, mdl[0]);
      check32(cur_goe, mdl[1]);
    end
  endtask

  task do_reset;
    begin
      @(negedge pclk);
      presetn = 1'b0; psel = 1'b0; penable = 1'b0;
      @(posedge pclk);
      #1;
      check32(cur_gout, 32'h0000_0000);
      check32(cur_goe, 32'h0000_0000);
      check1(cur_irq, 1'b0);
      @(posedge pclk);
      @(negedge pclk);
      presetn = 1'b1;
      for (j = 0; j < 8; j = j + 1) mdl[j] = 32'h0000_0000;
    end
  endtask

  // ------------------------------------------------------------------
  // One full suite against the selected instance
  // ------------------------------------------------------------------
  task run_suite(input s);
    begin
      sel   = s;
      n_cur = s ? 32 : 8;
      mask  = (n_cur == 32) ? 32'hFFFF_FFFF : ((32'd1 << n_cur) - 32'd1);
      top   = 32'd1 << (n_cur - 1);
      pins  = 32'h0000_0000;

      // Phase 0: reset values
      phase = 0;
      do_reset;
      check_regs;
      apb_read(A_INTR_STATUS, 32'h0000_0000, 1'b0);
      check1(cur_irq, 1'b0);

      // Phase 1: read/write registers, strobes, bits above N, pins
      phase = 1;
      for (i = 0; i < 8; i = i + 1) begin
        if (i != 2) begin
          a8 = {i[5:0], 2'b00};
          wr_reg(a8, 32'hFFFF_FFFF, 4'hF);    apb_read(a8, mdl[i], 1'b0);
          check32(cur_gout, mdl[0]); check32(cur_goe, mdl[1]);
          wr_reg(a8, 32'h0000_0000, 4'hF);    apb_read(a8, mdl[i], 1'b0);
          wr_reg(a8, 32'hA5C3_96E1, 4'b0101); apb_read(a8, mdl[i], 1'b0);
          check32(cur_gout, mdl[0]); check32(cur_goe, mdl[1]);
          wr_reg(a8, 32'h1234_5678, 4'b1010); apb_read(a8, mdl[i], 1'b0);
          wr_reg(a8, 32'hFFFF_FFFF, 4'b0000); apb_read(a8, mdl[i], 1'b0);
          wr_reg(a8, 32'h8000_0001 | top, 4'b1001); apb_read(a8, mdl[i], 1'b0);
          check32(cur_gout, mdl[0]); check32(cur_goe, mdl[1]);
          wr_reg(a8, 32'h0000_0000, 4'hF);    apb_read(a8, mdl[i], 1'b0);
        end
      end
      tick(2);
      apb_write(A_INTR_STATUS, 32'hFFFF_FFFF, 4'hF, 1'b0);
      apb_read(A_INTR_STATUS, 32'h0000_0000, 1'b0);
      check_regs;

      // Phase 2: PSLVERR policy, unmapped and read-only accesses
      phase = 2;
      wr_reg(A_DATA_OUT,    32'h5A5A_5A5A, 4'hF);
      wr_reg(A_DIR,         32'hC3C3_C3C3, 4'hF);
      wr_reg(A_INTR_RISE,   32'h1111_1111, 4'hF);
      wr_reg(A_INTR_FALL,   32'h2222_2222, 4'hF);
      wr_reg(A_INTR_ENABLE, 32'h4444_4444, 4'hF);
      for (i = 0; i < 24; i = i + 1) begin
        apb_write(bad_addr(i), 32'hFFFF_FFFF, 4'hF, 1'b1);
      end
      apb_write(A_DATA_IN, 32'hFFFF_FFFF, 4'hF, 1'b1);
      check_regs;
      apb_read(A_INTR_STATUS, 32'h0000_0000, 1'b0);
      for (i = 0; i < 24; i = i + 1) begin
        apb_read(bad_addr(i), 32'h0000_0000, 1'b1);
      end
      wr_reg(A_DATA_OUT,    32'h0000_0000, 4'hF);
      wr_reg(A_DIR,         32'h0000_0000, 4'hF);
      wr_reg(A_INTR_RISE,   32'h0000_0000, 4'hF);
      wr_reg(A_INTR_FALL,   32'h0000_0000, 4'hF);
      wr_reg(A_INTR_ENABLE, 32'h0000_0000, 4'hF);
      check_regs;

      // Phase 3: DATA_IN sampling, read only, no loopback
      phase = 3;
      set_pins(32'h5A5A_A5A5);
      apb_read(A_DATA_IN, pins & mask, 1'b0);
      apb_write(A_DATA_IN, 32'h0000_0000, 4'hF, 1'b1);
      apb_read(A_DATA_IN, pins & mask, 1'b0);
      set_pins(32'hA5A5_5A5A);
      apb_read(A_DATA_IN, pins & mask, 1'b0);
      wr_reg(A_DIR,      32'hFFFF_FFFF, 4'hF);
      wr_reg(A_DATA_OUT, 32'hFFFF_FFFF, 4'hF);
      set_pins(32'h0F0F_0F0F);
      apb_read(A_DATA_IN, pins & mask, 1'b0);
      check32(cur_gout, mask);
      check32(cur_goe, mask);
      wr_reg(A_DIR,      32'h0000_0000, 4'hF);
      wr_reg(A_DATA_OUT, 32'h0000_0000, 4'hF);
      set_pins(32'h0000_0000);
      apb_read(A_DATA_IN, 32'h0000_0000, 1'b0);
      apb_read(A_INTR_STATUS, 32'h0000_0000, 1'b0);

      // Phase 4: rising edge, cycle-exact irq, fires once
      phase = 4;
      wr_reg(A_INTR_ENABLE, 32'hFFFF_FFFF, 4'hF);
      wr_reg(A_INTR_RISE, 32'h0000_0007 | top, 4'hF);
      set_pins(32'h0000_0001 | top);
      @(posedge pclk); #1; check1(cur_irq, 1'b0);   // edge E: sampled
      @(posedge pclk); #1; check1(cur_irq, 1'b1);   // E+1: status set
      apb_read(A_INTR_STATUS, (32'h0000_0001 | top) & mask, 1'b0);
      apb_write(A_INTR_STATUS, 32'h0000_0007 | top, 4'hF, 1'b0);
      check1(cur_irq, 1'b0);
      apb_read(A_INTR_STATUS, 32'h0000_0000, 1'b0);
      tick(3);
      apb_read(A_INTR_STATUS, 32'h0000_0000, 1'b0);
      check1(cur_irq, 1'b0);

      // Phase 5: falling edge
      phase = 5;
      wr_reg(A_INTR_RISE, 32'h0000_0000, 4'hF);
      wr_reg(A_INTR_FALL, 32'h0000_0007 | top, 4'hF);
      set_pins(32'h0000_0000);
      @(posedge pclk); #1; check1(cur_irq, 1'b0);
      @(posedge pclk); #1; check1(cur_irq, 1'b1);
      apb_read(A_INTR_STATUS, (32'h0000_0001 | top) & mask, 1'b0);
      apb_write(A_INTR_STATUS, 32'hFFFF_FFFF, 4'hF, 1'b0);
      apb_read(A_INTR_STATUS, 32'h0000_0000, 1'b0);
      tick(3);
      apb_read(A_INTR_STATUS, 32'h0000_0000, 1'b0);
      wr_reg(A_INTR_FALL, 32'h0000_0000, 4'hF);

      // Phase 6: one-cycle pulse with both edges enabled
      phase = 6;
      wr_reg(A_INTR_RISE, 32'h0000_0010, 4'hF);
      wr_reg(A_INTR_FALL, 32'h0000_0010, 4'hF);
      set_pins(32'h0000_0010);
      set_pins(32'h0000_0000);
      tick(3);
      apb_read(A_INTR_STATUS, 32'h0000_0010, 1'b0);
      apb_write(A_INTR_STATUS, 32'h0000_0010, 4'hF, 1'b0);
      apb_read(A_INTR_STATUS, 32'h0000_0000, 1'b0);
      wr_reg(A_INTR_RISE, 32'h0000_0000, 4'hF);
      wr_reg(A_INTR_FALL, 32'h0000_0000, 4'hF);

      // Phase 7: high level sets again after a clear
      phase = 7;
      wr_reg(A_INTR_HIGH, 32'h0000_0004 | top, 4'hF);
      tick(2);
      apb_read(A_INTR_STATUS, 32'h0000_0000, 1'b0);
      set_pins(32'h0000_0004 | top);
      @(posedge pclk); #1; check1(cur_irq, 1'b0);
      @(posedge pclk); #1; check1(cur_irq, 1'b1);
      apb_read(A_INTR_STATUS, (32'h0000_0004 | top) & mask, 1'b0);
      apb_write(A_INTR_STATUS, 32'h0000_0004 | top, 4'hF, 1'b0);
      apb_read(A_INTR_STATUS, (32'h0000_0004 | top) & mask, 1'b0);
      set_pins(32'h0000_0000);
      tick(3);
      apb_write(A_INTR_STATUS, 32'h0000_0004 | top, 4'hF, 1'b0);
      apb_read(A_INTR_STATUS, 32'h0000_0000, 1'b0);
      check1(cur_irq, 1'b0);
      wr_reg(A_INTR_HIGH, 32'h0000_0000, 4'hF);

      // Phase 8: low level sets again after a clear
      phase = 8;
      wr_reg(A_INTR_LOW, 32'h0000_0008, 4'hF);
      apb_read(A_INTR_STATUS, 32'h0000_0008, 1'b0);
      apb_write(A_INTR_STATUS, 32'h0000_0008, 4'hF, 1'b0);
      apb_read(A_INTR_STATUS, 32'h0000_0008, 1'b0);
      set_pins(32'h0000_0008);
      tick(3);
      apb_write(A_INTR_STATUS, 32'h0000_0008, 4'hF, 1'b0);
      apb_read(A_INTR_STATUS, 32'h0000_0000, 1'b0);
      wr_reg(A_INTR_LOW, 32'h0000_0000, 4'hF);
      set_pins(32'h0000_0000);
      tick(2);
      apb_read(A_INTR_STATUS, 32'h0000_0000, 1'b0);

      // Phase 9: write-1-to-clear of some bits, with strobes
      phase = 9;
      wr_reg(A_INTR_RISE, 32'hFFFF_FFFF, 4'hF);
      set_pins(32'hFFFF_FFFF);
      tick(2);
      exp_st = mask;
      apb_read(A_INTR_STATUS, exp_st, 1'b0);
      apb_write(A_INTR_STATUS, 32'hFFFF_FFFF, 4'b0000, 1'b0);
      apb_read(A_INTR_STATUS, exp_st, 1'b0);
      apb_write(A_INTR_STATUS, 32'h0000_0005, 4'hF, 1'b0);
      exp_st = exp_st & ~(32'h0000_0005 & mask);
      apb_read(A_INTR_STATUS, exp_st, 1'b0);
      apb_write(A_INTR_STATUS, 32'hFFFF_FF00, 4'b0010, 1'b0);
      exp_st = exp_st & ~(32'h0000_FF00 & mask);
      apb_read(A_INTR_STATUS, exp_st, 1'b0);
      apb_write(A_INTR_STATUS, 32'h00AA_00F0, 4'b1100, 1'b0);
      exp_st = exp_st & ~(32'h00AA_0000 & mask);
      apb_read(A_INTR_STATUS, exp_st, 1'b0);
      apb_write(A_INTR_STATUS, 32'hFFFF_FFFF, 4'hF, 1'b0);
      apb_read(A_INTR_STATUS, 32'h0000_0000, 1'b0);
      wr_reg(A_INTR_RISE, 32'h0000_0000, 4'hF);
      set_pins(32'h0000_0000);
      tick(2);

      // Phase 10: interrupt mask
      phase = 10;
      wr_reg(A_INTR_ENABLE, 32'h0000_0000, 4'hF);
      wr_reg(A_INTR_RISE, 32'h0000_0001, 4'hF);
      set_pins(32'h0000_0001);
      tick(2);
      check1(cur_irq, 1'b0);
      apb_read(A_INTR_STATUS, 32'h0000_0001, 1'b0);
      wr_reg(A_INTR_ENABLE, 32'h0000_0002, 4'hF);
      check1(cur_irq, 1'b0);
      wr_reg(A_INTR_ENABLE, 32'h0000_0001, 4'hF);
      check1(cur_irq, 1'b1);
      wr_reg(A_INTR_ENABLE, 32'h0000_0000, 4'hF);
      check1(cur_irq, 1'b0);
      apb_read(A_INTR_STATUS, 32'h0000_0001, 1'b0);
      apb_write(A_INTR_STATUS, 32'h0000_0001, 4'hF, 1'b0);
      apb_read(A_INTR_STATUS, 32'h0000_0000, 1'b0);
      set_pins(32'h0000_0000);
      tick(2);

      // Phase 11: a detection beats a clear on the same edge
      phase = 11;
      set_pins(32'h0000_0001);
      tick(2);
      set_pins(32'h0000_0000);
      tick(2);
      apb_read(A_INTR_STATUS, 32'h0000_0001, 1'b0);
      @(negedge pclk);
      paddr = A_INTR_STATUS; pwrite = 1'b1; pwdata = 32'h0000_0001; pstrb = 4'hF;
      psel = 1'b1; penable = 1'b0;
      pins = 32'h0000_0001;   // sampled at setup edge, detected at completion edge
      @(negedge pclk);
      penable = 1'b1;
      #1;
      check1(cur_pready, 1'b1);
      check1(cur_pslverr, 1'b0);
      @(posedge pclk);
      #1;
      psel = 1'b0; penable = 1'b0; pwrite = 1'b0; pstrb = 4'h0;
      apb_read(A_INTR_STATUS, 32'h0000_0001, 1'b0);
      apb_write(A_INTR_STATUS, 32'h0000_0001, 4'hF, 1'b0);
      apb_read(A_INTR_STATUS, 32'h0000_0000, 1'b0);
      // Control: the pin rises one cycle earlier, so the clear wins.
      set_pins(32'h0000_0000);
      tick(2);
      set_pins(32'h0000_0001);
      apb_write(A_INTR_STATUS, 32'h0000_0001, 4'hF, 1'b0);
      apb_read(A_INTR_STATUS, 32'h0000_0000, 1'b0);
      wr_reg(A_INTR_RISE, 32'h0000_0000, 4'hF);
      set_pins(32'h0000_0000);
      tick(2);

      // Phase 12: reset again with state set and an interrupt pending
      phase = 12;
      wr_reg(A_DATA_OUT,    32'hFFFF_FFFF, 4'hF);
      wr_reg(A_DIR,         32'hFFFF_FFFF, 4'hF);
      wr_reg(A_INTR_ENABLE, 32'hFFFF_FFFF, 4'hF);
      wr_reg(A_INTR_HIGH,   32'hFFFF_FFFF, 4'hF);
      set_pins(32'hFFFF_FFFF);
      tick(2);
      check1(cur_irq, 1'b1);
      check32(cur_gout, mask);
      check32(cur_goe, mask);
      do_reset;
      check_regs;
      apb_read(A_INTR_STATUS, 32'h0000_0000, 1'b0);
      check1(cur_irq, 1'b0);
      set_pins(32'h0000_0000);
      tick(2);
    end
  endtask

  // ------------------------------------------------------------------
  // Main
  // ------------------------------------------------------------------
  initial begin
    if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = {64{8'h00}};
    run_suite(1'b0);
    run_suite(1'b1);
    $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
    $finish;
  end

  // Watchdog: a hung run still ends with a failing verdict.
  initial begin
    #5000000;
    $error("watchdog timeout");
    $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed + 1);
    $finish;
  end

endmodule

`default_nettype wire
